#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ldap.h>

int parse_credentials(const char *input, char **domain, char **username) {
    char *sep = strchr(input, '\\');
    if (!sep) sep = strchr(input, '@');
    if (!sep) return -1;

    size_t domain_len = sep - input;
    *domain = malloc(domain_len + 1);
    strncpy(*domain, input, domain_len);
    (*domain)[domain_len] = '\0';

    *username = strdup(sep + 1);
    return 0;
}

void construct_base_dn(const char *domain, char *base_dn, size_t max_len) {
    char *token;
    char *copy = strdup(domain);
    char *saveptr;
    base_dn[0] = '\0';

    token = strtok_r(copy, ".", &saveptr);
    while (token) {
        if (base_dn[0] != '\0') strncat(base_dn, ",", max_len - strlen(base_dn) - 1);
        strncat(base_dn, "dc=", max_len - strlen(base_dn) - 1);
        strncat(base_dn, token, max_len - strlen(base_dn) - 1);
        token = strtok_r(NULL, ".", &saveptr);
    }
    free(copy);
}

int search_user(const char *base_dn, const char *username) {
    LDAP *ld = NULL;
    int rc;
    char filter[256];

    snprintf(filter, sizeof(filter), "(uid=%s)", username);

    rc = ldap_initialize(&ld, "ldap://localhost");
    if (rc != LDAP_SUCCESS) {
        fprintf(stderr, "ldap_initialize failed: %s\n", ldap_err2string(rc));
        return -1;
    }

    rc = ldap_simple_bind_s(ld, NULL, NULL);
    if (rc != LDAP_SUCCESS) {
        fprintf(stderr, "ldap_simple_bind failed: %s\n", ldap_err2string(rc));
        ldap_unbind_ext_s(ld, NULL, NULL);
        return -1;
    }

    rc = ldap_search_ext_s(ld, base_dn, LDAP_SCOPE_SUBTREE, filter, NULL, 0, NULL, NULL, NULL, 0, NULL);
    if (rc != LDAP_SUCCESS) {
        fprintf(stderr, "ldap_search failed: %s\n", ldap_err2string(rc));
        ldap_unbind_ext_s(ld, NULL, NULL);
        return -1;
    }

    LDAPMessage *res = NULL;
    rc = ldap_search_ext_s(ld, base_dn, LDAP_SCOPE_SUBTREE, filter, NULL, 0, NULL, NULL, NULL, 0, &res);
    if (rc != LDAP_SUCCESS) {
        fprintf(stderr, "ldap_search failed: %s\n", ldap_err2string(rc));
        ldap_unbind_ext_s(ld, NULL, NULL);
        return -1;
    }

    LDAPMessage *entry = ldap_first_entry(ld, res);
    if (!entry) {
        printf("No user found\n");
        ldap_msgfree(res);
        ldap_unbind_ext_s(ld, NULL, NULL);
        return -1;
    }

    while (entry) {
        char *dn = ldap_get_dn(ld, entry);
        printf("DN: %s\n", dn);
        ldap_memfree(dn);

        BerElement *ber = NULL;
        char *attr = ldap_first_attribute(ld, entry, &ber);
        while (attr) {
            char **vals = ldap_get_values(ld, entry, attr);
            if (vals) {
                for (int i = 0; vals[i]; i++) {
                    printf("%s: %s\n", attr, vals[i]);
                }
                ldap_value_free(vals);
            }
            ldap_memfree(attr);
            attr = ldap_next_attribute(ld, entry, ber);
        }
        if (ber) ber_free(ber, 0);

        printf("---\n");
        entry = ldap_next_entry(ld, entry);
    }

    ldap_msgfree(res);
    ldap_unbind_ext_s(ld, NULL, NULL);
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <DOMAIN\\username or username@domain>\n", argv[0]);
        return 1;
    }

    char *domain = NULL;
    char *username = NULL;

    if (parse_credentials(argv[1], &domain, &username) != 0) {
        fprintf(stderr, "Invalid format. Use DOMAIN\\username or username@domain\n");
        return 1;
    }

    char base_dn[256];
    construct_base_dn(domain, base_dn, sizeof(base_dn));

    printf("Searching for user: %s in domain: %s (base DN: %s)\n", username, domain, base_dn);

    int result = search_user(base_dn, username);

    free(domain);
    free(username);

    return result;
}
